                _ = g.gml_script_instance_create(self, other, (self.vars[g.VAR_xpos] + 16.0), ((self.vars[g.VAR_ypos] - 80.0) + 16.0), k.OBJ_oKaliHead);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("a"))) {
                _ = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oChest);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("I"))) {
                _ = g.gml_script_instance_create(self, other, (self.vars[g.VAR_xpos] + 16.0), (self.vars[g.VAR_ypos] + 12.0), k.OBJ_oGoldIdol);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("B"))) {
                _ = g.gml_script_instance_create(self, other, (self.vars[g.VAR_xpos] + 16.0), (self.vars[g.VAR_ypos] + 12.0), k.OBJ_oGiantTikiHead);
                _ = g.gml_script_tile_add(self, other, k.SPR_bgTiki, 0.0, 0.0, 32.0, 64.0, self.vars[g.VAR_xpos], (self.vars[g.VAR_ypos] + 32.0), 10001.0);
                _ = g.gml_script_tile_add(self, other, k.SPR_bgTikiArms, (16.0 * g.gml_script_rand(self, other, 0.0, 2.0)), 0.0, 16.0, 16.0, (self.vars[g.VAR_xpos] + 32.0), (self.vars[g.VAR_ypos] + 32.0), 10001.0);
                _ = g.gml_script_tile_add(self, other, k.SPR_bgTikiArms, (16.0 * g.gml_script_rand(self, other, 0.0, 2.0)), 16.0, 16.0, 16.0, (self.vars[g.VAR_xpos] - 16.0), (self.vars[g.VAR_ypos] + 32.0), 10001.0);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("Q"))) {
                if (rt.strEq(self.strs[g.SVAR_shopType], "Craps")) {
                    _ = g.gml_script_tile_add(self, other, k.SPR_bgDiceSign, 0.0, 0.0, 48.0, 32.0, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], 9004.0);
                }
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("q"))) {
                self.vars[g.VAR_n] = g.gml_script_rand(self, other, 1.0, 6.0);
                g.gml_script_scrGenerateItem(self, other, (self.vars[g.VAR_xpos] + 8.0), (self.vars[g.VAR_ypos] + 8.0), 1.0);
                rt.ivarSet(rt.deref(self.vars[g.VAR_obj], self, other), g.VAR_inDiceHouse, 1.0);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("+"))) {
                self.vars[g.VAR_obj] = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oSolid);
                api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sIceBlock);
                rt.ivarSet(rt.deref(self.vars[g.VAR_obj], self, other), g.VAR_shopWall, 1.0);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("W"))) {
                if ((rt.truthy(g.globals.murderer) or rt.gt(g.globals.thiefLevel, 0.0))) {
                    if (rt.truthy(g.globals.isDamsel)) {
                        _ = g.gml_script_tile_add(self, other, k.SPR_bgWanted, 32.0, 0.0, 32.0, 32.0, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], 9004.0);
                    } else if (rt.truthy(g.globals.isTunnelMan)) {
                        _ = g.gml_script_tile_add(self, other, k.SPR_bgWanted, 64.0, 0.0, 32.0, 32.0, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], 9004.0);
                    } else {
                        _ = g.gml_script_tile_add(self, other, k.SPR_bgWanted, 0.0, 0.0, 32.0, 32.0, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], 9004.0);
                    }
                }
            } else if ((rt.veq(self.vals[g.VVAR_tile], rt.vs(".")) and !rt.truthy(api.collision_point(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oSolid, 0.0, 0.0)))) {
                if (rt.eq(g.gml_script_rand(self, other, 1.0, 10.0), 1.0)) {
                    self.vars[g.VAR_obj] = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oBlock);
                } else {
                    self.vars[g.VAR_obj] = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oBrick);
                }
                rt.ivarSet(rt.deref(self.vars[g.VAR_obj], self, other), g.VAR_shopWall, 1.0);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("b"))) {
                self.vars[g.VAR_obj] = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oBrickSmooth);
                rt.ivarSet(rt.deref(self.vars[g.VAR_obj], self, other), g.VAR_shopWall, 1.0);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("l"))) {
                if (rt.truthy(rt.ivar(rt.deref(k.OBJ_oGame, self, other), g.VAR_damsel))) {
                    _ = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oLampRed);
                } else {
                    _ = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oLamp);
                }
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("K"))) {
                self.vars[g.VAR_obj] = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oShopkeeper);
                rt.svarSet(rt.deref(self.vars[g.VAR_obj], self, other), g.SVAR_style, self.strs[g.SVAR_shopType]);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("k"))) {
                self.vars[g.VAR_obj] = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oSign);
                if (rt.strEq(self.strs[g.SVAR_shopType], "General")) {
                    api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sSignGeneral);
                } else if (rt.strEq(self.strs[g.SVAR_shopType], "Bomb")) {
                    api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sSignBomb);
                } else if (rt.strEq(self.strs[g.SVAR_shopType], "Weapon")) {
                    api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sSignWeapon);
                } else if (rt.strEq(self.strs[g.SVAR_shopType], "Clothing")) {
                    api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sSignClothing);
                } else if (rt.strEq(self.strs[g.SVAR_shopType], "Rare")) {
                    api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sSignRare);
                } else if (rt.strEq(self.strs[g.SVAR_shopType], "Craps")) {
                    api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sSignCraps);
                } else if (rt.strEq(self.strs[g.SVAR_shopType], "Kissing")) {
                    api.iset_sprite_index(rt.deref(self.vars[g.VAR_obj], self, other), k.SPR_sSignKissing);
                }
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("i"))) {
                g.gml_script_scrShopItemsGen(self, other);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("d"))) {
                _ = g.gml_script_instance_create(self, other, (self.vars[g.VAR_xpos] + 8.0), (self.vars[g.VAR_ypos] + 8.0), k.OBJ_oDice);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("D"))) {
                self.vars[g.VAR_obj] = g.gml_script_instance_create(self, other, (self.vars[g.VAR_xpos] + 8.0), (self.vars[g.VAR_ypos] + 8.0), k.OBJ_oDamsel);
                rt.ivarSet(rt.deref(self.vars[g.VAR_obj], self, other), g.VAR_forSale, 1.0);
                rt.ivarSet(rt.deref(self.vars[g.VAR_obj], self, other), g.VAR_status, 5.0);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("s"))) {
                if (rt.eq(g.gml_script_rand(self, other, 1.0, 10.0), 1.0)) {
                    _ = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oSnake);
                } else if (rt.eq(g.gml_script_rand(self, other, 1.0, 2.0), 1.0)) {
                    _ = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oBrick);
                }
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("S"))) {
                _ = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oSnake);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("T"))) {
                _ = g.gml_script_instance_create(self, other, (self.vars[g.VAR_xpos] + 8.0), (self.vars[g.VAR_ypos] + 8.0), k.OBJ_oRubyBig);
            } else if (rt.veq(self.vals[g.VVAR_tile], rt.vs("M"))) {
                _ = g.gml_script_instance_create(self, other, self.vars[g.VAR_xpos], self.vars[g.VAR_ypos], k.OBJ_oBrick);
                self.vars[g.VAR_obj] = g.gml_script_instance_create(self, other, (self.vars[g.VAR_xpos] + 8.0), (self.vars[g.VAR_ypos] + 8.0), k.OBJ_oMattock);
                rt.ivarSet(rt.deref(self.vars[g.VAR_obj], self, other), g.VAR_cost, 0.0);
                rt.ivarSet(rt.deref(self.vars[g.VAR_obj], self, other), g.VAR_forSale, 0.0);
            }
        }
    }
}
